import { defineConfig } from 'vitest/config';
import type { Plugin } from 'vite';
import react from '@vitejs/plugin-react';
import { VitePWA } from 'vite-plugin-pwa';
import splashScreens from './scripts/splash-screens.json';

// Served from https://<user>.github.io/bebislogg/. Changing this path moves the
// app to a new storage origin/scope, so existing data must be moved via export/import.
const BASE = '/bebislogg/';

/** iOS startup images, one per screen size (generated by scripts/generate-icons.mjs). */
function appleStartupImages(): Plugin {
  return {
    name: 'apple-startup-images',
    transformIndexHtml: () =>
      splashScreens.map(({ w, h, dpr }) => ({
        tag: 'link',
        attrs: {
          rel: 'apple-touch-startup-image',
          href: `${BASE}splash/splash-${w}x${h}@${dpr}.png`,
          media: `(device-width: ${w}px) and (device-height: ${h}px) and (-webkit-device-pixel-ratio: ${dpr}) and (orientation: portrait)`,
        },
        injectTo: 'head',
      })),
  };
}

export default defineConfig({
  base: BASE,
  plugins: [
    react(),
    appleStartupImages(),
    VitePWA({
      registerType: 'autoUpdate',
      manifest: {
        id: BASE,
        name: 'Bebislogg',
        short_name: 'Bebislogg',
        description: 'Sömn, matning och D-droppar för en bebis. All data stannar i telefonen.',
        lang: 'sv',
        display: 'standalone',
        orientation: 'portrait',
        background_color: '#161826',
        theme_color: '#161826',
        icons: [
          { src: 'icons/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
          { src: 'icons/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
          { src: 'icons/icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
        ],
      },
      workbox: {
        globPatterns: ['**/*.{js,css,html,svg,png,ico,webmanifest}'],
        // iOS reads the startup images when the app is added; they need not be cached.
        globIgnores: ['**/splash/**'],
      },
    }),
  ],
  test: {
    environment: 'node',
    // Date logic is tested against Swedish DST, also in CI (which runs in UTC).
    env: { TZ: 'Europe/Stockholm' },
  },
});
